## 3. Result-Generation Logic (form data → recommendation)

Source: `client/src/lib/spinalFusionLogic.ts`

```typescript
export type SpineLevel = "lumbar" | "cervical" | "thoracic";

export type SpinalFusionInput = {
  age: string; spineRegion?: string; spineLevel: SpineLevel | ""; bmi: string; primaryDiagnosis: string;
  symptomDurationMonths: string;
  painScore: string; odiScore?: string; ndiScore?: string;
  symptoms?: string[]; conservativeTherapyMonths: string;
  conservativeTherapies: string[]; imagingFindings: string[];
  neurologicDeficits: string[]; comorbidities: string[];
  instability?: boolean; myelopathy?: boolean; progressiveNeurologicDeficit?: boolean;
  activeInfection: boolean; severeOsteoporosis?: boolean; medicallyUnfit?: boolean;
  priorSpineSurgery: boolean; malignancy: boolean;
};

export type COR = "I" | "IIa" | "IIb" | "III";

export function getCORLabel(cor: COR): string {
  return { I: "Class I — Recommended", IIa: "Class IIa — Reasonable", IIb: "Class IIb — May Be Considered", III: "Class III — Not Recommended" }[cor];
}
export function getCORColor(cor: COR): string {
  return { I: "border-green-500 text-green-700", IIa: "border-blue-500 text-blue-700", IIb: "border-yellow-500 text-yellow-700", III: "border-red-500 text-red-700" }[cor];
}

export function assessSpinalFusion(input: SpinalFusionInput) {
  const conservMonths = parseFloat(input.conservativeTherapyMonths) || 0;
  const odi = parseFloat(input.odiScore || '0') || 0;
  const ndi = parseFloat(input.ndiScore || '0') || 0;
  const painScore = parseFloat(input.painScore) || 0;

  const contraindications: string[] = [];
  if (input.activeInfection) contraindications.push("Active infection — absolute contraindication");
  if (input.severeOsteoporosis) contraindications.push("Severe osteoporosis — high risk of hardware failure; requires optimization");
  if (input.medicallyUnfit) contraindications.push("Medically unfit for surgery");

  if (contraindications.length > 0) {
    return { recommendation: "Spinal Fusion Contraindicated or Requires Optimization", cor: "III" as COR, loe: "C", urgency: "Contraindicated", rationale: ["Contraindications identified — address before proceeding."], contraindications, optimizationSteps: ["Address all contraindications", "Bone density optimization if osteoporosis present"] };
  }

  const rationale: string[] = [];
  const optimizationSteps: string[] = [];
  let cor: COR = "IIb";
  let urgency = "Elective";

  if (input.progressiveNeurologicDeficit || input.myelopathy) {
    cor = "I"; urgency = "Urgent";
    rationale.push("Progressive neurologic deficit or myelopathy — urgent surgical evaluation required");
    rationale.push("Delay in treatment risks permanent neurologic injury");
  } else if (input.instability && conservMonths >= 6 && (odi >= 40 || ndi >= 30)) {
    cor = "I"; urgency = "Appropriate";
    rationale.push("Documented spinal instability with significant functional impairment");
    rationale.push("Adequate conservative therapy trial completed");
    rationale.push("Functional assessment scores support surgical intervention");
  } else if (conservMonths >= 6 && (odi >= 40 || ndi >= 30) && painScore >= 6) {
    cor = "IIa"; urgency = "Reasonable";
    rationale.push("Significant functional impairment with adequate conservative therapy failure");
    rationale.push("Fusion is reasonable after shared decision-making");
  } else if (conservMonths < 6) {
    cor = "IIb"; urgency = "Continue Conservative Therapy";
    rationale.push("Conservative therapy trial insufficient — continue for ≥6 months");
    optimizationSteps.push("Continue PT, medications, and injections for ≥6 months total");
    optimizationSteps.push("Document functional scores at each visit (ODI or NDI)");
  } else {
    cor = "IIb"; urgency = "Insufficient Criteria";
    rationale.push("Functional impairment criteria not fully met");
    optimizationSteps.push("Complete ODI (lumbar) or NDI (cervical) functional assessment");
    optimizationSteps.push("Document pain scores at multiple visits");
  }

  if ((input.symptoms || []).includes("smoking")) optimizationSteps.push("Smoking cessation required — significantly impairs fusion rates");
  if ((input.symptoms || []).includes("diabetes")) optimizationSteps.push("Optimize glycemic control (HbA1c <8%)");

  return { recommendation: cor === "I" ? "Spinal Fusion Recommended" : cor === "IIa" ? "Spinal Fusion Reasonable" : "Spinal Fusion — Additional Criteria Needed", cor, loe: input.instability ? "A" : "B", urgency, rationale, contraindications, optimizationSteps };
}
